'use strict';
let activityChecked=0,activityBusy=false;
const investigationLabel={supported:'Supported thesis',wait:'Wait',rejected:'Rejected',unverified:'Could not verify'};
function investigationCard(a,review){return `<article class="setup-card investigation-card"><div class="home-heading"><b>${esc(a.type==='briefing'?'Market briefing':a.target)}</b><span class="investigation-verdict">${investigationLabel[review?.verdict||a.verdict]}</span></div><h3>${esc(a.title)}</h3><small>${stamp(a.publishedAt)} · public-evidence research</small><p>${esc(a.whyNow)}</p><p><b>Entry:</b> ${esc(a.entry)}</p><p><b>Risk:</b> ${esc(a.risk)}</p><p><b>Next check:</b> ${esc(a.nextCheck)}</p><details><summary>Decision & independent challenge</summary><p><b>Investigation · ${investigationLabel[a.verdict]}:</b> ${esc(a.reason)}</p>${review?`<p><b>Challenge · ${investigationLabel[review.verdict]}:</b> ${esc(review.reason)}</p><small>${stamp(review.publishedAt)}</small><p>${review.sources.map((u,i)=>researchLink(u,'Review source '+(i+1))).join(' · ')}</p>`:'<p>Independent challenge pending. This case has not passed a second review.</p>'}<p>Agreement is not proof of an edge. Claims and causal connections still require judgment.</p></details><p>${a.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}</p>${a.type==='stock'?`<button data-ticker="${esc(a.target)}">Chart ↗</button> <button data-map="${esc(a.target)}">Map ↗</button>`:a.type==='contract'?`<button data-research-contract="${esc(a.target)}">Current contract & odds ↗</button>`:''}</article>`}
async function refreshResearchActivity(force=false){if(activityBusy||!force&&Date.now()-activityChecked<900000)return;activityBusy=true;try{const d=await getLiveJSON('/api/research/activity'),findings=d.items.filter(i=>i.phase==='finding'),latest=[],seen=new Set();for(const a of findings){const key=a.type+':'+a.target;if(!seen.has(key)){latest.push(a);seen.add(key)}}const status=d.status;const caption=status?`${esc(status.status)} · ${stamp(status.checkedAt)} · ${status.investigations}/3 investigations · ${status.challenges}/2 challenges today`:'First monitoring run pending';
for(const [id,limit]of [['homeResearchActivity',3],['dailyResearchActivity',20]]){const el=document.getElementById(id);if(!el)continue;el.innerHTML=`<div class="home-heading"><h2>Research desk · what we checked</h2>${id==='homeResearchActivity'?'<button data-view="daily">All findings →</button>':''}</div><p class="home-caption">${caption}</p><div class="setup-grid">${latest.slice(0,limit).map(a=>investigationCard(a,d.items.find(i=>i.id===a.id&&i.phase==='challenge'))).join('')||'<p>No completed investigation yet. This does not mean there are no market opportunities.</p>'}</div>${id==='dailyResearchActivity'?`<details><summary>Earlier versions & follow-ups</summary><div class="setup-grid">${findings.filter(a=>!latest.some(l=>l.id===a.id)).map(a=>investigationCard(a,d.items.find(i=>i.id===a.id&&i.phase==='challenge'))).join('')||'<p>No earlier versions yet.</p>'}</div></details><p class="home-caption">Latest 150 investigation/review records shown. Earlier records are retained. Research runs while the configured computer is awake and online.</p>`:''}`;}activityChecked=Date.now()}catch{for(const id of ['homeResearchActivity','dailyResearchActivity']){const el=document.getElementById(id);if(el&&!el.querySelector('article'))el.textContent='Research activity unavailable; retry shortly.'}}finally{activityBusy=false}}
function renderResearchPriority(){const el=document.getElementById('researchPriority');if(el){el.checked=!!workspaceState.researchPriority;el.disabled=!workspaceState.user}}
if(typeof window!=='undefined'){
 refreshResearchActivity();renderResearchPriority();document.getElementById('researchPriority').onchange=async e=>{await workspaceAction({kind:'researchPriority',enabled:e.target.checked});renderResearchPriority()};
 document.addEventListener('click',async e=>{if(e.target.closest('#dailyRefresh,#refreshHomeSetups'))refreshResearchActivity(true);const b=e.target.closest('[data-research-contract]');if(b){changeView('predictions');await loadPredictions();if(pmFeed?.value?.markets.some(m=>m.id===b.dataset.researchContract))selectPrediction(b.dataset.researchContract);else notify('Contract is not in the current open-market feed.')}});
 setInterval(()=>{if(!document.hidden)refreshResearchActivity()},900000);
}
